import networkx as nx,itertools,collections,json

def myc(k):
 g=nx.Graph();g.add_nodes_from(range(2*k+1))
 for i in range(k):
  j=(i+1)%k;g.add_edges_from([(i,j),(i,k+j),(j,k+i)])
 for i in range(k):g.add_edge(2*k,k+i)
 return g
for k in [3,5,7]:
 g=myc(k);N=len(g); res={}
 # I1,I2 independent, residual. enumerate independent subsets then bipartite induced of deleted set
 indeps=[]
 def rec(i,mask):
  if i==N:indeps.append(mask);return
  rec(i+1,mask)
  if not any((mask>>j)&1 for j in g[i]):rec(i+1,mask|(1<<i))
 rec(0,0)
 for a in indeps:
  for b in indeps:
   if a&b:continue
   R=g.subgraph([i for i in g if not ((a|b)>>i)&1]).copy()
   R.remove_nodes_from(list(nx.isolates(R)))
   if R.number_of_edges()>8:continue
   key=nx.weisfeiler_lehman_graph_hash(R)
   res[key]=R
 vals=sorted(res.values(),key=lambda x:(x.number_of_edges(),len(x)))
 mins=[]
 for R in vals:
  if any(nx.algorithms.isomorphism.GraphMatcher(R,Q).subgraph_is_monomorphic() for Q in mins):continue
  mins.append(R)
 print('k',k,'indeps',len(indeps),'minimal',[(len(x),x.number_of_edges(),sorted(dict(x.degree()).values()),nx.to_graph6_bytes(nx.convert_node_labels_to_integers(x),header=False).decode().strip()) for x in mins],flush=True)

