    assert H.subgraph(set(V)-a).number_of_edges()==1

def mul(a,b):
    c=[0]*(len(a)+len(b)-1)
    for i,x in enumerate(a):
        for j,y in enumerate(b):c[i+j]+=x*y
    return c

def cycles(k, unbalanced=False):
    m=3*k; a=m+int(unbalanced);b=m-int(unbalanced)
    q=[1]
